def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Kruskal's algorithm
    # Sort all edges
    edges = []
    for u in range(n):
        for v, w in graph[u]:
            if u < v:  # avoid duplicates
                edges.append((w, u, v))

    edges.sort()

    # Union-Find data structure
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        parent[root_v] = root_u
        return True

    total_cost = 0
    count = 0

    for w, u, v in edges:
        if union(u, v):
            total_cost += w
            count += 1
            if count == n - 1:
                break

    # Check if all cities are connected
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return -1

    return total_cost

